xql_query:
// ============================================================
// Rule: FTG_DOS Policy Possible DDoS Attack (Copy)
// Vendor: Fortigate
// Objective:
// Detect activity associated with FTG_DOS Policy Possible DDoS Attack (Copy).
// Severity: SEV_040_HIGH
// Category: OTHER
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0002 - Execution
// Technique: T1204 - User Execution
// Technique: T1204.002 - User Execution: Malicious File
// Tactic: TA0001 - Initial Access

dataset = fortinet_fortigate_raw
| filter cat = "utm:app-ctrl"
  and (FTNTFGTappcat = "Proxy" or FTNTFGTappcat = "P2P")
| alter
    timestamp = _time,
    src_ip = src,
    dst_ip = dst,
    app_category = FTNTFGTapp,
    application = app,
    action_taken = act,
    log_message = msg,
    request_origin = dhost,
    user = duser,
    message = msg,
    device_name = _reporting_device_name
| fields timestamp, device_name, src_ip, dst_ip, app_category, application, message
